return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Plugin Axtarışa keçin','Activate %s' => '%s aktivləşdirin','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> quraşdırılması və aktivləşdirilməsi üçün <strong>%2$s</strong> tələb edir. <a href="%4$s">%3$s</a>','Enter your code here' => 'Kodunuzu bura daxil edin','Add %s' => '%s əlavə edin','Remove' => 'Sil','Order number and receipt will be sent to this email address.' => 'Sifariş nömrəsi və qəbz bu e-poçt ünvanına göndəriləcək.','Apartment, unit, building, floor, etc.' => 'Mənzil, bölmə, bina, mərtəbə və s.','Shipping phone' => 'Çatdırılma telefonu','Only used for shipping-related questions.' => 'Yalnız göndərmə ilə bağlı suallar üçün istifadə olunur.','Single step' => 'Tək addım','Click to go to the order summary' => 'Sifariş xülasəsinə keçmək üçün klikləyin','Cart total:' => 'Səbətin cəmi:','Proceed to %s' => '%s ilə davam edin','Proceed to contact' => 'Əlaqə saxlamağa davam edin','Proceed to shipping' => 'Göndərməyə davam edin','Proceed to billing' => 'Fakturaya keçin','Proceed to payment' => 'Ödəməyə davam edin','Shipping method' => 'Göndərmə üsulu','Additional notes' => 'Əlavə qeydlər','Payment method' => 'Ödəniş üsulu','Step %1$s of %2$s' => '%2$s addımdan %1$s','Change: %s' => 'Dəyişiklik: %s','Not selected yet.' => 'Hələ seçilməyib.','Same as shipping address' => 'Göndərmə ünvanı ilə eynidir','Same as billing address' => 'Faktura ünvanı ilə eynidir','Order summary' => 'Sifariş xülasəsi','Edit cart' => 'Səbətə düzəliş edin','Did you mean %s?' => '%s nəzərdə tuturdunuz?','Change email address to: {suggestion-value}' => 'E-poçt ünvanını dəyişdirin: {suggestion-value}','This is a required field.' => 'Bu tələb olunan sahədir.','This is not a valid email address.' => 'Bu etibarlı e-poçt ünvanı deyil.','This field does not match the related field value.' => 'Bu sahə müvafiq sahə dəyərinə uyğun gəlmir.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; CPF nömrəsi yanlışdır.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ nömrəsi &quot;{cnpj_number}&quot; etibarsızdır.','(Required)' => '(Tələb olunur)','Checkout Header - Desktop' => 'Checkout Header - İş masası','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Böyük ekranlar üçün kassa başlığında vidjetləri göstərin. Yalnız plaqinin yoxlama başlığından istifadə edildikdə göstərilir.','Checkout Header - Mobile' => 'Checkout Header - Mobil','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Mobil cihazlar üçün yoxlama başlığının altında vidcetləri göstərin. Yalnız plaqinin yoxlama başlığından istifadə edildikdə göstərilir.','Checkout Sidebar' => 'Yoxlama Yan Paneli','Display widgets on the checkout sidebar after the order summary.' => 'Sifariş xülasəsindən sonra ödəniş yan panelində vidjetləri göstərin.','Checkout Order Summary' => 'Ödəniş Sifarişinin xülasəsi','Display widgets inside the order summary at the checkout page.' => 'Ödəniş səhifəsində vidjetləri sifariş xülasəsi daxilində göstərin.','Checkout Below Place Order' => 'Sifariş verdikdən sonra yoxlayın','Display widgets below the place order button at the checkout page.' => 'Vidcetləri ödəmə səhifəsində yerləşdirmə düyməsinin altında göstərin.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Vidjetləri ödəniş altbilgisində göstərin. Yalnız plaqinin yoxlama altbilgisindən istifadə edildikdə göstərilir.','Classic' => 'Klassik','Boxed' => 'Qutulu','Split' => 'bölün','Minimalist' => 'Minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz tərəfindən Fluid Checkout və Çatdırılma Tarixi plaginləri','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>CodeRockz tərəfindən WooCommerce (pulsuz və PRO) üçün Çatdırılma və Alma Tarixi Vaxtı plaginlərindən istifadə etdiyinizi aşkar etdik. Bu plaginlərlə inteqrasiya Fluid Checkout PRO-a köçürüldü.</p>','Upgrade to PRO' => 'PRO-ya təkmilləşdirin','Fluid Checkout database updated successfully' => 'Fluid Checkout verilənlər bazası uğurla yeniləndi','The database changes where applied successfully.' => 'Uğurla tətbiq olunduğu yerdə verilənlər bazası dəyişir.','Dismiss' => 'Rədd et','Fluid Checkout database update' => 'Fluid Checkout verilənlər bazası yeniləməsi','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Verilənlər bazasında bəzi dəyişikliklər tələb olunur. İstənilən yeniləmədə olduğu kimi, <strong>davam etməzdən əvvəl veb saytınızın tam ehtiyat nüsxəsini çıxarmağınızı</strong> tövsiyə edirik.','Update database' => 'Verilənlər bazasını yeniləyin','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout Divi Builder yoxlama planı ilə uyğun gəlmir','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout işləmək üçün klassik WooCommerce qısa kod əsaslı yoxlama formasına ehtiyac duyur. Yoxlama səhifəsinin görünüşünü və hissini fərdiləşdirmək üçün Divi Builder-dən istifadə edərkən, klassik qısa kodlar yoxlama səhifəsinin hər bir hissəsi üçün Divi Builder-in xüsusi vidjetləri ilə əvəz olunur. Bu fərdi vidjetlər Fluid Checkout ilə uyğun gəlmir.</p><p> Divi Builder vidcetlərini <code>[woocommerce_checkout]</code> qısa kodu olan mətn vidceti ilə əvəz edərək yoxlama səhifənizi redaktə edin.</p>','Edit the checkout page' => 'Ödəniş səhifəsini redaktə edin','Read the documentation.' => 'Sənədləri oxuyun.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Fluid Checkout istifadə edərkən almanlaşmış PRO çox addımlı yoxlama funksiyası deaktiv edilməlidir','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout istifadə edərkən, Germanized PRO plaginindən çox addımlı xüsusiyyət lazımsız olur və <strong>yeni sifarişləri emal edərkən kritik xətalara</strong> səbəb ola bilər. Lütfən, plagin parametrlərində Germanized PRO multistep checkout funksiyasını deaktiv edin.','Go to Germanized settings' => 'Almanlaşdırılmış parametrlərə keçin','Thanks for choosing Fluid Checkout!' => 'Fluid Checkout-u seçdiyiniz üçün təşəkkür edirik!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Artıq bir müddətdir ki, plaqindən istifadə edirsiniz. İndiyə qədər bunu necə bəyənirsiniz?<br> Zəhmət olmasa bizə tez qiymət verin, hər bir rəyi qiymətləndiririk və bu, bizi plaqini təkmilləşdirməyə təşviq edir :)','Rate the plugin' => 'Plugini qiymətləndirin','I need help!' => 'Mənə kömək lazımdır!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Quadlayers tərəfindən WooCommerce Checkout Manager-in bəzi xüsusiyyətləri onu Fluid Checkout ilə istifadə edərkən gözlənildiyi kimi işləməyə bilər. Əlavə məlumat və alternativ həllər üçün <a href="%s">sənədlərimizi</a> oxuyun.','Read documentation' => 'Sənədləri oxuyun','Don\'t show this again' => 'Bunu bir daha göstərməyin','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Daha çox dizayn şablonları','Optimized cart page' => 'Optimallaşdırılmış səbət səhifəsi','Optimized order received / thank you page' => 'Optimallaşdırılmış sifariş qəbul edildi / təşəkkür səhifəsi','Edit cart contents at checkout page' => 'Səbətin məzmununu ödəmə səhifəsində redaktə edin','Account matching / user matching' => 'Hesab uyğunluğu / istifadəçi uyğunluğu','Trust symbols on the cart and thank you pages' => 'Səbətdə güvən simvolları və təşəkkür səhifələri','More positions for the coupon code on the checkout page' => 'Ödəniş səhifəsində kupon kodu üçün daha çox mövqelər','International phone numbers' => 'Beynəlxalq telefon nömrələri','Gift messages and packing slips' => 'Hədiyyə mesajları və qablaşdırma vərəqələri','Local pickup and in-store collection' => 'Yerli götürmə və mağazada kolleksiya','EU-VAT Assistant' => 'AB-ƏDV köməkçisi','I already have it – Hide this offer' => 'Məndə artıq var – Bu təklifi gizlədin','Activated' => 'Aktivləşdirilib','Address book' => 'Ünvan kitabçası','Select an image' => 'Şəkil seçin','Cart layout' => 'Səbətin düzülüşü','Cart optimizations' => 'Səbətin optimallaşdırılması','Enable cart page optimizations' => 'Səbət səhifəsinin optimallaşdırılmasını aktivləşdirin','Header and footer template' => 'Başlıq və altbilgi şablonu','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Diqqəti yayındırmayan səhifənin başlıq və altbilgisindən istifadə edib-etməməyi və ya hazırda aktiv mövzunun başlıq və altbilgisini saxlayıb-saxlamamağa nəzarət edir.','Distraction free header and footer' => 'Diqqəti yayındırmayan başlıq və altbilgi','Theme\'s header and footer' => 'Mövzunun başlığı və altbilgisi','Cart elements' => 'Səbət elementləri','Make the order summary stay visible on the cart page while scrolling' => 'Sürüşdürərkən sifariş xülasəsinin səbət səhifəsində görünən qalmasını təmin edin','Coupon codes' => 'Kupon kodları','Hidden' => 'Gizli','Before the cart items section' => 'Səbət elementləri bölməsindən əvvəl','Inside the cart items section' => 'Səbət əşyaları bölməsinin içərisində','After the cart items section' => 'Səbət əşyaları bölməsindən sonra','Before the shipping section' => 'Göndərmə bölməsindən əvvəl','After the shipping section' => 'Göndərmə bölməsindən sonra','Before the order summary' => 'Sifariş xülasəsindən əvvəl','Inside the order summary' => 'Sifariş xülasəsinin içərisində','Before the order totals' => 'Sifarişin cəmindən əvvəl','After the order totals' => 'Sifariş yekunlaşdıqdan sonra','After the order summary' => 'Sifarişin xülasəsindən sonra','Shipping' => 'Çatdırılma','Select position where to display the shipping costs and calculator on the cart page.' => 'Səbət səhifəsində göndərmə xərclərinin və kalkulyatorun göstəriləcəyi yeri seçin.','Display as a cart section' => 'Səbət bölməsi kimi göstərin','Cross-sells' => 'Çapraz satış','Select position where to display the cross-sells section on the cart page.' => 'Səbət səhifəsində çarpaz satış bölməsinin göstəriləcəyi yeri seçin.','Before the cart actions' => 'Səbət hərəkətlərindən əvvəl','After the cart actions' => 'Səbət hərəkətlərindən sonra','Layout of cross-sell items on the cart page.' => 'Səbət səhifəsində çarpaz satış əşyalarının yerləşdirilməsi.','Optimized horizontal cross-sells layout' => 'Optimallaşdırılmış üfüqi çarpaz satış planı','Theme\'s cross-sells layout' => 'Mövzunun çarpaz satış planı','Number of cross-sell items to display on the cart page' => 'Səbət səhifəsində göstəriləcək çarpaz satış maddələrinin sayı','Add widget areas to the cart page' => 'Səbət səhifəsinə vidcet sahələri əlavə edin','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Bu vidjet sahələri səbət səhifəsində güvən simvolları və etibar nişanları əlavə etmək üçün istifadə olunur.','Checkout' => 'Yoxlama','Checkout layout' => 'Kassa tərtibatı','Design template' => 'Dizayn şablonu','Dark mode' => 'Qaranlıq rejim','Enable dark mode' => 'Qaranlıq rejimi aktivləşdirin','Logo image' => 'Loqo şəkli','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Ödəniş səhifəsinin başlığında göstəriləcək bir şəkil seçin. Yalnız diqqəti yayındırmayan başlıq və altbilgidən istifadə edərkən tətbiq edilir.','Header background color' => 'Başlıq fon rəngi','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Ödəniş səhifəsinin başlığı üçün fon rəngi seçin. Yalnız diqqəti yayındırmayan başlıq və altbilgidən istifadə edərkən tətbiq edilir.','HTML color value. ie: #f3f3f3' => 'HTML rəng dəyəri. yəni: #f3f3f3','Page background color' => 'Səhifənin fon rəngi','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Ödəniş səhifəsi üçün fon rəngi seçin. <em>Bədən</em> elementinə rəng tətbiq olunur.','Footer background color' => 'Altbilgi fon rəngi','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Yoxlama səhifəsinin altbilgisi üçün fon rəngi seçin. Yalnız diqqəti yayındırmayan başlıq və altbilgidən istifadə edərkən tətbiq edilir.','Progress bar' => 'Tərəqqi çubuğu','Display the checkout progress bar when using multi-step checkout layout' => 'Çox mərhələli ödəniş sxemindən istifadə edərkən ödəniş tərəqqi panelini göstərin','Make the checkout progress bar stay visible while scrolling' => 'Sürüşdürərkən ödəniş tərəqqi panelinin görünən qalmasını təmin edin','Express checkout' => 'Ekspress ödəniş','Enable the express checkout section' => 'Ekspress ödəmə bölməsini aktivləşdirin','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Dəstəklənən ödəniş şlüzlərində bu funksiya aktiv olduqda, ödəniş zamanı ekspress ödəmə bölməsini göstərir.','Display express checkout buttons in one line for larger screens' => 'Daha böyük ekranlar üçün ekspress yoxlama düymələrini bir sətirdə göstərin','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Uyğun ekspress ödəniş ödəniş şlüzü ilə ödəniş edərkən əlavə ödəniş tələb olunan sahələrinə məhəl qoymayın','Make the order summary stay visible while scrolling' => 'Sürüşdürərkən sifariş xülasəsinin görünən qalmasını təmin edin','Choose a background color for the order summary section.' => 'Sifarişin xülasəsi bölməsi üçün fon rəngi seçin.','Highlight the order totals row in the order summary table' => 'Sifarişin xülasəsi cədvəlində sifarişlərin cəmi sırasını vurğulayın','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Sifarişin xülasəsi bölməsində vurğulanmış fon rəngi olmadığı zaman ən faydalıdır. Fluid Checkout PRO-dan istifadə edərkən Səbət, Qəbul edilən Sifariş və Sifarişlərə Baxış səhifələrinə də tətbiq oluna bilər.','Action link on the order summary at checkout.' => 'Ödəniş zamanı sifariş xülasəsində fəaliyyət linki.','Edit cart link' => 'Səbət bağlantısını redaktə edin','Cart items count' => 'Səbətdəki əşyaların sayı','Link to shop page' => 'Mağaza səhifəsinə keçid','Cart items' => 'Səbət əşyaları','Hide cart items errors at the checkout page' => 'Səbət elementləri səhvlərini ödəmə səhifəsində gizlədin','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Səbət elementləri səhvləri mesajını ödəmə səhifəsinin yuxarı hissəsində göstərməyin. Satınalmanı tamamlamaq üçün ödəniş formasını təqdim edərkən, bu səhv mesajları həmişə göstəriləcək.','Place order' => 'Sifariş verin','Define the position to display "Place order" and terms checkbox section.' => '&quot;Sifariş verin&quot; və şərtlərin qeyd qutusu bölməsini göstərmək üçün mövqeyi müəyyənləşdirin.','Some options might not be compatible with some plugins and themes.' => 'Bəzi seçimlər bəzi plaginlər və mövzularla uyğun olmaya bilər.','Below the payment section' => 'Ödəniş bölməsinin altında','Below the order summary' => 'Sifariş xülasəsinin altında','Both below the payment section and the order summary' => 'Həm ödəniş bölməsinin altında, həm də sifariş xülasəsi','Add widget areas to the checkout page' => 'Ödəniş səhifəsinə vidcet sahələri əlavə edin','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Bu widget sahələri yoxlama səhifəsində etibar simvolları və etibar nişanları əlavə etmək üçün istifadə olunur.','Display the coupon codes section title' => 'Kupon kodları bölməsinin başlığını göstərin','Select position where to display the coupon codes section on the checkout page.' => 'Ödəniş səhifəsində kupon kodları bölməsinin göstəriləcəyi yeri seçin.','Before the checkout steps' => 'Ödəniş addımlarından əvvəl','As a substep before payment methods' => 'Ödəniş üsullarından əvvəl alt addım kimi','As a substep after payment methods' => 'Ödəniş üsullarından sonra alt addım kimi','Default button style' => 'Defolt düymə tərzi','"Add" link button' => '&quot;Əlavə et&quot; link düyməsi','Checkout fields' => 'Yoxlama sahələri','Optional fields' => 'Könüllü sahələr','Hide optional fields behind a link button' => 'Əlaqə düyməsinin arxasında isteğe bağlı sahələri gizlədin','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Açıq giriş sahələrinin sayını azaltmaq üçün bu seçimi yoxlamaq tövsiyə olunur, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">araşdırmanı oxuyun</a> .','Do not hide "Address line 2" fields behind a link button' => '&quot;Ünvan xətti 2&quot; sahələrini keçid düyməsinin arxasında gizlətməyin','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Yalnız müştərilərin çoxunun &quot;Ünvan xətti 2&quot; sahəsinə ehtiyac duyduqda və ya düzgün çatdırılma ünvanının əldə edilməsi vacib olduqda (yəni qida və digər tez xarab olan məhsulların çatdırılması zamanı) tövsiyə olunur.','Billing address' => 'Faktura ünvanı','Select position where to display the billing address section on the checkout page.' => 'Ödəniş səhifəsində faktura ünvanı bölməsinin göstəriləcəyi yeri seçin.','As a step before shipping' => 'Göndərmədən əvvəl bir addım olaraq','As a sub-step before the shipping address section' => 'Göndərmə ünvanı bölməsindən əvvəl bir alt addım olaraq','As a sub-step after the shipping address section' => 'Göndərmə ünvanı bölməsindən sonra bir alt addım olaraq','As a step after shipping' => 'Göndərmədən sonra bir addım olaraq','As a sub-step before the payment section' => 'Ödəniş bölməsindən əvvəl bir alt addım olaraq','Force billing and shipping addresses to the same (single section)' => 'Faktura və göndərmə ünvanlarını eyni (tək bölmə) üçün məcbur edin','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;Göndərmə/faktura ünvanı ilə eyni&quot; üçün qeyd qutusu defolt olaraq işarələnib','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => '&quot;Göndərmə ünvanı ilə eyni&quot; qeyd xanası ilk olaraq göndərmə ünvanı bölməsi göstərildikdə, defolt olaraq işarələndiyi kimi başlayacaq.<br> Faktura ünvanı bölməsi ilk dəfə göstərildikdə, &quot;Faturalandırma ünvanı ilə eyni&quot; qeyd qutusu defolt olaraq işarələndiyi kimi başlayacaq.<br> Ödəniş zamanı açıq giriş sahələrinin sayını əhəmiyyətli dərəcədə azaltmaq üçün bu seçimi yoxlamaq tövsiyə olunur, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">araşdırmanı oxuyun</a> .','Highlight the billing address section in the checkout form' => 'Ödəniş formasında faktura ünvanı bölməsini vurğulayın','Shipping address' => 'Çatdırılma ünvanı','Highlight the shipping address section in the checkout form' => 'Ödəniş formasında göndərmə ünvanı bölməsini vurğulayın','Shipping methods' => 'Göndərmə üsulları','Choose in which position to display the shipping methods section.' => 'Göndərmə üsulları bölməsinin hansı mövqedə göstəriləcəyini seçin.','Before shipping address' => 'Göndərmə ünvanı əvvəl','After shipping address' => 'Çatdırılma ünvanından sonra','Local pickup' => 'Yerli alma','Removes shipping address section when a local pickup shipping method is selected.' => 'Yerli götürmə göndərmə üsulu seçildikdə çatdırılma ünvanı bölməsini silir.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Yerli götürmə göndərmə üsulu seçildikdə göndərmə ünvanını götürmə nöqtəsi yeri ilə əvəz edir.','Choose which address to save as the shipping address for local pickup orders.' => 'Yerli götürmə sifarişləri üçün çatdırılma ünvanı kimi yadda saxlanacaq ünvanı seçin.','Save the selected pickup location' => 'Seçilmiş götürmə yerini yadda saxlayın','Save same as the billing address' => 'Faktura ünvanı kimi yadda saxlayın','Do not save any shipping address' => 'Heç bir göndərmə ünvanını saxlamayın','Company name field for shipping address' => 'Göndərmə ünvanı üçün şirkət adı sahəsi','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Ödəniş formasındakı göndərmə ünvanı bölməsi üçün şirkət adı sahəsinin görünməsini dəyişdirin.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Sahə defolt görünmə vəziyyəti olan &quot;isteğe bağlı&quot; olaraq təyin edilərsə, digər plaginlərə lazım olan hər hansı dəyişikliyi tətbiq etmək üçün heç bir dəyişiklik tətbiq edilməyəcək.','Hidden (remove field)' => 'Gizli (sahəni silin)','Optional' => 'Könüllü','Required' => 'Tələb olunur','Add shipping phone field to the checkout form.' => 'Ödəniş formasına göndərmə telefonu sahəsi əlavə edin.','Choose in which step to display the shipping phone field.' => 'Göndərmə telefonu sahəsinin hansı addımda göstəriləcəyini seçin.','Contact step' => 'Əlaqə addımı','Billing phone' => 'Billing telefonu','Add billing phone field to the checkout form.' => 'Ödəniş formasına faktura telefonu sahəsi əlavə edin.','Choose in which step to display the billing phone field.' => 'Faturalandırma telefonu sahəsinin hansı addımda göstəriləcəyini seçin.','Show country code beside the flag' => 'Bayrağın yanında ölkə kodunu göstərin','Show an example of a valid phone number inside phone fields' => 'Telefon sahələrində etibarlı telefon nömrəsinin nümunəsini göstərin','Do not change placeholders' => 'Yer tutucuları dəyişməyin','Show if not defined' => 'Müəyyən edilmədikdə göstərin','Always show' => 'Həmişə göstər','Order notes' => 'Sifariş qeydləri','Define the visibility of the additional order notes field.' => 'Əlavə sifariş qeydləri sahəsinin görünməsini müəyyənləşdirin.','Gift options' => 'Hədiyyə seçimləri','Allow customers to add a gift message and other gift related options to the order.' => 'Müştərilərə sifarişə hədiyyə mesajı və digər hədiyyə ilə bağlı seçimlər əlavə etməyə icazə verin.','Display the gift message as part of the order details table instead of a separate section' => 'Hədiyyə mesajını ayrıca bölmə əvəzinə sifariş təfərrüatları cədvəlinin bir hissəsi kimi göstərin','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Bu seçim sifarişin təsdiqi səhifəsinə (təşəkkür səhifəsi) və hesab səhifələrindəki sifariş təfərrüatlarına, e-poçt məktublarına və qablaşdırma vərəqələrinə təsir göstərir.','Account matching' => 'Hesab uyğunluğu','Enable the account matching feature' => 'Hesab uyğunluğu funksiyasını aktivləşdirin','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Müştərinin əlaqə məlumatları ilə hesab artıq mövcud olduqda, qonaq müştərinin sifarişlərini mövcud hesabı ilə əlaqələndirin.','Display message when an account exists with the email address provided' => 'Göstərilən e-poçt ünvanı ilə hesab mövcud olduqda mesajı göstərin','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Hesab yaratma sahələrini bildiriş və daxil olmaq seçimi ilə əvəz edir. Bəzi kontekstlərdə müştərilərin məxfiliyini qorumaq üçün bu seçimi qeyri-aktiv etmək tövsiyə oluna bilər.','Dashboard' => 'İdarə paneli','Integrations' => 'İnteqrasiyalar','License keys' => 'Lisenziya açarları','Visit our website for more information about our plugins and add-ons.' => 'Plaginlərimiz və əlavələrimiz haqqında ətraflı məlumat üçün veb saytımıza daxil olun.','Order pay page' => 'Sifariş ödəmə səhifəsi','Order pay' => 'Sifariş ödənişi','Enable order pay page optimizations' => 'Sifariş ödəmə səhifəsi optimallaşdırmasını aktivləşdirin','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Müştəridən ödəniş gözlənilən mövcud sifarişlər üçün ödəniş səhifəsinin tərtibatını dəyişir.','Add widget areas to the order pay page' => 'Sifariş ödəmə səhifəsinə vidcet sahələri əlavə edin','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Bu widget sahələri sifariş ödəniş səhifəsində etibar simvolları və etibar nişanları əlavə etmək üçün istifadə olunur.','Thank you page & order details layout' => 'Səhifə və sifariş təfərrüatları tərtibatı üçün təşəkkür edirik','Order details optimizations' => 'Sifariş detallarının optimallaşdırılması','Enable thank you page and order details optimizations' => 'Təşəkkür səhifəsi və sifariş detallarının optimallaşdırılmasını aktiv edin','Changes the layout of order details on the thank you page and account pages.' => 'Təşəkkür səhifəsində və hesab səhifələrində sifariş təfərrüatlarının tərtibatını dəyişir.','Enable order details customizations on email notifications' => 'E-poçt bildirişlərində sifariş detallarının fərdiləşdirilməsini aktivləşdirin','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Yeni bölmələri göstərin və e-poçt bildirişlərində bölmələrin sırasını dəyişdirin. E-poçt bildirişlərində sifariş detallarının üslubları dəyişməz olaraq qalır.','Thank you page' => 'Təşəkkür səhifəsi','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Bu seçimlər, alınan sifariş və ya sifariş təsdiqləmə səhifələri kimi tanınan təşəkkür səhifəsinə təsir göstərir.','Order details layout' => 'Sifariş detallarının tərtibatı','Display the order details with wide layout on the thank you page' => 'Təşəkkür səhifəsində sifariş təfərrüatlarını geniş tərtibatla göstərin','Add widget areas to the thank you page' => 'Təşəkkür səhifəsinə vidcet sahələri əlavə edin','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Bu widget sahələri təşəkkür səhifəsində etibar simvolları və etibar nişanları əlavə etmək üçün istifadə olunur.','Order actions' => 'Fəaliyyətləri sifariş edin','Choose in which position to display the order actions.' => 'Sifariş hərəkətlərinin hansı mövqedə göstəriləcəyini seçin.','Inside the order overview' => 'Sifarişin ümumi görünüşü','After the order overview' => 'Sifarişə baxışdan sonra','After order sections' => 'Sifarişdən sonra bölmələr','Order status' => 'Sifariş statusu','Display the order status progress bar' => 'Sifariş statusunun tərəqqi çubuğunu göstərin','Choose in which position to display the section.' => 'Bölmənin hansı mövqedə göstəriləcəyini seçin.','After the order overview and payment instructions' => 'Sifarişin icmalı və ödəniş təlimatlarından sonra','Before the order items section' => 'Sifariş maddələri bölməsindən əvvəl','Inside the order items section' => 'Sifariş maddələri bölməsində','After the order items section' => 'Sifariş maddələri bölməsindən sonra','On the sidebar' => 'Yan paneldə','Order downloads' => 'Yükləmələri sifariş edin','Gift message' => 'Hədiyyə mesajı','Tools' => 'Alətlər','Troubleshooting' => 'Problemlərin aradan qaldırılması','Debug options' => 'Sazlama seçimləri','Debug mode' => 'Sazlama rejimi','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Sazlama rejimindən istifadə veb saytın performansına təsir göstərir. Bu seçimi yalnız problemləri həll edərkən istifadə edin.','Load unminified assets' => 'Minimallaşdırılmamış aktivləri yükləyin','Enhanced select fields' => 'Təkmilləşdirilmiş seçim sahələri','Fix automatic zoom-in on form fields' => 'Forma sahələrinin avtomatik böyüdülməsini düzəldin','Set <code>font-size</code> inside form fields to 16px' => 'Forma sahələrində <code>font-size</code> 16px olaraq təyin edin','Fluid Checkout' => 'Maye yoxlanışı','Settings' => 'Parametrlər','Support' => 'Dəstək','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'Daha çox seçimləri açmaq üçün <a target="_blank" href="%s">PRO-ya təkmilləşdirin</a> .','(PRO)' => '(PRO)','(experimental)' => '(eksperimental)','Please verify your phone number.' => 'Zəhmət olmasa telefon nömrənizi doğrulayın.','The Bluehost Plugin' => 'Bluehost Plugin','Custom fields' => 'Fərdi sahələr','Enable custom shipping email field' => 'Fərdi göndərmə e-poçt sahəsini aktivləşdirin','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Aktivləşdirildikdə, Bluehost plaginindən göndərmə e-poçt sahəsi ödəniş formasına əlavə olunacaq.','Captcha Pro by BestWebSoft' => 'BestWebSoft tərəfindən Captcha Pro','Captcha position' => 'Captcha mövqeyi','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Captcha bölməsini göstərmək üçün mövqeyi müəyyənləşdirin. Bəzi vəzifələr seçilmiş captcha növündən asılı olaraq işləməyə bilər.','Selecting a pickup point is required before proceeding.' => 'Davam etməzdən əvvəl götürmə nöqtəsini seçmək tələb olunur.','Pickup point' => 'Qəbul nöqtəsi','Pickup point not selected yet.' => 'Qəbul nöqtəsi hələ seçilməyib.','Pickup point:' => 'Qəbul nöqtəsi:','Mailchimp for WooCommerce' => 'WooCommerce üçün Mailchimp','Subscribe checkbox' => 'Abunə olun onay qutusu','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Ödəniş səhifəsində abunə mövqeyini yoxlayın və onu həmişə əlaqə addımında göstərin','Before Shipping Address' => 'Çatdırılmadan əvvəl Ünvan','(originally "%s")' => '(əslində &quot;%s&quot;)','After Shipping Address' => 'Çatdırıldıqdan sonra Ünvan','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint ilə göndərmə zamanı toplama məntəqəsinin seçilməsi tələb olunur.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Əgər yoxlanılıbsa, istifadəçilərə e-poçtdakı yazı xətaları barədə məlumat verir. (Fluid Checkout funksiyanı təklif etdiyi üçün bu funksiya deaktiv edilib. Bu seçimə edilən dəyişikliklər qüvvəyə minməyəcək)','Enable Mail Check: (disabled feature)' => 'Poçt yoxlanışını aktivləşdirin: (aktiv xüsusiyyət)','Carrier:' => 'Daşıyıcı:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce E-poçt Marketinqi','Sign up checkbox position' => 'Qeyd xanasının mövqeyi','Move the sign up checkbox to the contact step' => 'Qeydiyyat qutusunu əlaqə addımına köçürün','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Aktivləşdirildikdə, onay qutusu Sendinblue plagin parametrlərində müəyyən edilmiş displey yerindən asılı olmayaraq əlaqə addımına köçürüləcək.','Theme Betheme' => 'Mövzu Betheme','Checkout progress' => 'Yoxlamanın gedişi','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Kassa, səbət və sifariş səhifələrində Betheme-dən yoxlama addımları bölməsini çıxarın.','Theme Fennik' => 'Mövzu Fennik','Breadcrumbs' => 'Çörək qırıntıları','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fluid Checkout başlıq və altbilgidən istifadə edərkən Fennik mövzusundan çörək qırıntıları bölməsini çıxarın.','Theme Go' => 'Theme Go','My account layout' => 'Mənim hesab düzümü','Enable wide layout on "My account" page.' => '&quot;Hesabım&quot; səhifəsində geniş tərtibatı aktivləşdirin.','Theme Impreza' => 'Impreza mövzusu','Header' => 'Başlıq','Spacing for site header at the checkout page (in pixels)' => 'Ödəniş səhifəsində sayt başlığı üçün boşluq (piksellə)','Only applicable when using the Impreza theme header at the checkout page.' => 'Yalnız yoxlama səhifəsində Impreza mövzu başlığından istifadə edərkən tətbiq edilir.','Theme Kapee' => 'Mövzu Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Kassa, səbət və sifariş səhifələrində Kapee mövzusundan ödəniş addımları bölməsini çıxarın.','Theme Porto' => 'Mövzu Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Kassa, səbət və sifariş səhifələrində Porto mövzusundan ödəniş addımları bölməsini çıxarın.','Theme Pressmart' => 'Mövzu Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Kassa, səbət və alınan sifariş səhifələrində Pressmart mövzusundan ödəniş addımları bölməsini çıxarın.','Theme The Gem' => 'Mövzu The Gem','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Fluid Checkout başlıq və altbilgidən istifadə edərkən The Gem mövzusundan yoxlama addımları bölməsini çıxarın.','Theme Woodmart' => 'Mövzu Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Fluid Checkout başlıq və altbilgidən istifadə edərkən Woodmart mövzusundan yoxlama addımları bölməsini çıxarın.','Checkout options' => 'Yoxlama seçimləri','Disable the theme checkout options' => 'Mövzunun yoxlama seçimlərini deaktiv edin','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Seçimlər məhsul şəklini, kəmiyyət sahəsini, sil düyməsini və mövzu ilə əlavə edilmiş məhsul səhifəsinə keçidi əks etdirir.','Theme Atomion' => 'Mövzu Atomion','Order progress' => 'Sifarişin gedişi','Display order progress from the theme' => 'Mövzudan sifariş tərəqqisini göstərin','Display the form field labels visible on the page' => 'Səhifədə görünən forma sahəsi etiketlərini göstərin','It is recommended to keep this option enabled for a better user experience.' => 'Daha yaxşı istifadəçi təcrübəsi üçün bu seçimi aktiv saxlamaq tövsiyə olunur.','Theme ZK Nito' => 'Mövzu ZK Nito','Add extra fields to the checkout form' => 'Ödəniş formasına əlavə sahələr əlavə edin','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Göndərmə ünvanı bölməsinə əlavə göndərmə e-poçtu və göndərmə telefonu sahəsi əlavə edir.','Go to the home page' => 'Əsas səhifəyə keçin','Skip to content' => 'Məzmuna keçin','Create an account' => 'Hesab yaradın','Log in to your account' => 'Hesabınıza daxil olun','Already have an account?' => 'Artıq hesabınız var?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s kimi daxil olub. <a href="%2$s">Çıxın</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Sifarişinizdə %s məbləğində ümumi məbləğ var. Əlavə ödəniş tələb olunmur.','Close and continue with checkout' => 'Bağlayın və ödənişə davam edin','Continue' => 'Davam et','Parcel terminal' => 'Bağlama terminalı','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Bu vidcet Fluid Checkout ilə əvəz edilmişdir.</p><p> Fluid Checkout istifadə edərkən, yoxlama səhifəsi düzgün işləmək üçün orijinal WooCommerce qısa kodundan <code>[woocommerce_checkout]</code> istifadə etməlidir.</p><p> Əlavə məlumat üçün Fluid Checkout sənədlərinə baş çəkin.</p>','Theme The7' => 'Mövzu 7','Additional header sections' => 'Əlavə başlıq bölmələri','Output additional header sections if enabled in the theme settings.' => 'Mövzu parametrlərində aktivləşdirilibsə, əlavə başlıq bölmələrini çıxarın.','More information' => 'Ətraflı məlumat','Pick a Locker' => 'Şkaf seçin','Page template' => 'Səhifə şablonu','Use `Order confirmation` page template for block-based themes' => 'Blok əsaslı mövzular üçün &quot;Sifariş təsdiqi&quot; səhifə şablonundan istifadə edin','Only applies when using a block-based theme.' => 'Yalnız blok əsaslı mövzudan istifadə edərkən tətbiq edilir.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Ödəniş forması','Apply styles to the Stripe payment form fields' => 'Stripe ödəniş forması sahələrinə üslubları tətbiq edin','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Aktiv edildikdə, Fluid Checkout plaginlə uyğunluq üçün optimallaşdırılmış üslubları tətbiq edəcək. Zolaqlı ödəniş forması sahələri üçün fərdi üslublardan istifadə edirsinizsə, bunu deaktiv etmək istəyə bilərsiniz.','Theme Nyture' => 'Nyture mövzusu','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout istifadə edərkən Nyture mövzusundan yoxlama addımları bölməsini çıxarın.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Müştərilərə mağaza admini tərəfindən əl ilə yaradılan və ya ödəniş zamanı tamamlanmayan sifarişlər üçün ödənişlər etməyə imkan verir.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers tərəfindən plagin WooCommerce Checkout Manager Fluid Checkout ilə uyğun gəlmir','Company name field for billing address' => 'Billinq ünvanı üçün şirkət adı sahəsi','Change visibility for the company name field for the billing address section on the checkout form.' => 'Ödəniş formasındakı faktura ünvanı bölməsi üçün şirkət adı sahəsinin görünməsini dəyişdirin.','Theme Bookshelf' => 'Mövzu kitab rəfi','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Fluid Checkout istifadə edərkən Bookshelf mövzusundan yoxlama addımları bölməsini çıxarın.','Account password' => 'Hesab parolu','An account will be created with the information provided at checkout when completing the order.' => 'Sifarişi yerinə yetirərkən ödəniş zamanı verilən məlumatlarla hesab yaradılacaq.','Choose the style of the progress bar.' => 'Tərəqqi çubuğunun üslubunu seçin.','Bars' => 'Barlar','Theme Ireca' => 'Mövzu Ireca','WooCommerce page layout' => 'WooCommerce səhifə tərtibatı','Force wide layout on WooCommerce pages' => 'WooCommerce səhifələrində geniş tərtibatı məcbur edin','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Bu, məzmun bölməsinin WooCommerce səhifələrində kassa, səbət, alınan sifariş, sifariş ödənişi və hesab səhifələri daxil olmaqla çox dar olmadığını təmin edir.','WooCommerce Smart Coupons' => 'WooCommerce Ağıllı Kuponlar','Position on checkout page' => 'Ödəniş səhifəsində mövqe','Choose where to display the available coupons section on the checkout page.' => 'Ödəniş səhifəsində mövcud kuponlar bölməsinin harada göstəriləcəyini seçin.','Before the progress bar' => 'Tərəqqi çubuğundan əvvəl','After the progress bar' => 'Tərəqqi çubuğundan sonra','Before coupon codes section' => 'Kupon kodları bölməsindən əvvəl','Format phone numbers according to the rules for each country.' => 'Telefon nömrələrini hər bir ölkə üçün qaydalara uyğun formatlaşdırın.','Use precise phone number validation' => 'Dəqiq telefon nömrəsi təsdiqindən istifadə edin','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Bu eksperimental xüsusiyyətdir və bütün quraşdırmalarda gözlənildiyi kimi işləməyə bilər. Ehtiyatla istifadə edin.','Phone number validation types used when precise validation is enabled.' => 'Dəqiq doğrulama aktiv olduqda istifadə edilən telefon nömrəsinin doğrulama növləri.','Mobile' => 'Mobil','Fixed line' => 'Sabit xətt','Toll free' => 'Pulsuz','Contact' => 'Əlaqə','Multi step' => 'Çoxmərhələli','2 columns' => '2 sütun','1 column' => '1 sütun','Before checkout steps' => 'Kassadan əvvəl addımlar','Or' => 'Və ya','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 sütun&quot;</em> ödəmə sxemindən istifadə edərkən bu seçim həmişə <em>&quot;Ödənişdən əvvəl addımlar&quot;</em> olaraq təyin edilir və masaüstü görünüşünə də tətbiq olunur.','Position for the extra order summary section on mobile.' => 'Mobil cihazda əlavə sifariş xülasəsi bölməsi üçün mövqe.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;Sayt başlığında&quot;</em> seçimi yalnız diqqəti yayındırmayan başlıqdan istifadə edərkən tətbiq olunur.','On the site header (requires distraction-free header)' => 'Sayt başlığında (diqqəti yayındırmayan başlıq tələb olunur)','Initial state for the expansible order summary section on mobile.' => 'Mobil cihazda genişləndirilə bilən sifariş xülasəsi bölməsi üçün ilkin vəziyyət.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Tənzimləyici tələblərə görə aşağıdakı ölkələr üçün <em>genişləndirilmiş</em> kimi təyin etməyi tövsiyə edirik: <strong>Almaniya</strong> , <strong>Avstriya</strong> , <strong>İsveçrə</strong> , <strong>Niderland</strong> , <strong>Polşa</strong> , <strong>Belçika</strong> və <strong>Fransa</strong> .','Collapsed' => 'Yığılmış','Expanded' => 'Genişləndirilmiş','Do not show' => 'Göstərməyin','yes' => 'bəli','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Göndərmə ünvanı bölməsindən sonra ödəniş ünvanı bölməsi göstərilərsə və ödəniş telefonu sahəsi &quot;tələb olunur&quot; olaraq təyin olunarsa, çatdırılma telefonu sahəsi &quot;tələb olunur&quot; kimi göstərilə bilər. Bu, həmin seçim işarələndikdə çatdırılma ünvanının ödəniş ünvanına kopyalana biləcəyini təmin etmək üçün lazımdır, əks halda müştəri ödəmə formasını doldura bilməyəcək.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Göndərmə ünvanı bölməsindən əvvəl ödəniş ünvanı bölməsi göstərilərsə və çatdırılma telefonu sahəsi &quot;tələb olunur&quot; olaraq təyin olunarsa, ödəniş telefonu sahəsi &quot;tələb olunur&quot; kimi göstərilə bilər. Bu, həmin seçim işarələndikdə çatdırılma ünvanının ödəniş ünvanına kopyalana biləcəyini təmin etmək üçün lazımdır, əks halda müştəri ödəmə formasını doldura bilməyəcək.','Settings profiles' => 'Parametrlər profilləri','Settings profile' => 'Parametrlər profili','You do not have permission to perform this action.' => 'Bu əməliyyatı yerinə yetirmək üçün icazəniz yoxdur.','You do not have permission to activate plugins.' => 'Pluginləri aktivləşdirmək üçün icazəniz yoxdur.','Missing plugin.' => 'Plugin çatışmır.','Plugin activated.' => 'Plugin aktivləşdirildi.','The following changes will be applied:' => 'Aşağıdakı dəyişikliklər tətbiq olunacaq:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Fluid Checkout 5.0 versiyasından bəri, parametrlər fərqli şəkildə saxlanılır. Lazım gələrsə, əvvəlki versiyalara endirməyə imkan vermək üçün köhnə seçimlər hələ də verilənlər bazasında saxlanılır.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Mağazanız təxminən 2 həftədir ki, yeni parametrlərdə işləyir, beləliklə verilənlər bazasında saxlanılan köhnə seçimləri təmizləyə bilərsiniz. Nəzərə alın ki, təmizləndikdən sonra plaginin əvvəlki versiyalarına keçməli olsanız, bütün parametrlər üçün standart dəyərlərdən istifadə edəcək.','Fluid Checkout settings cleanup' => 'Maye yoxlaması parametrlərinin təmizlənməsi','Delete leftover options' => 'Qalan seçimləri silin','Help us improve Fluid Checkout' => 'Maye Ödənişini təkmilləşdirməyimizə kömək edin','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Daha sürətli dəstək almaq və uyğunluğu təkmilləşdirmək və təsiri ölçmək üçün anonim sayt mühiti hesabatlarını Fluid Checkout ilə paylaşın. Müştəri, istifadəçi və ya həssas məlumatlar daxil edilməyib. Alətlər parametrlərindən istənilən vaxt nəyin paylaşılacağını seçə bilərsiniz.','Enable site environment reports' => 'Sayt mühiti hesabatlarını aktivləşdirin','Review settings' => 'Parametrləri nəzərdən keçirin','This preview has expired. Reload the admin page to start a new preview.' => 'Bu önizləmənin müddəti bitib. Yeni önizləməyə başlamaq üçün admin səhifəsini yenidən yükləyin.','Preview expired' => 'Önizləmə müddəti bitdi','Orders cannot be placed in the preview.' => 'Sifarişlər önizləmədə yerləşdirilə bilməz.','Logging in is not available in the preview.' => 'Önizləmədə giriş mümkün deyil.','Accounts cannot be created in the preview.' => 'Önizləmədə hesablar yaradıla bilməz.','Requests to other sites are blocked in the preview.' => 'Önizləmədə digər saytlara edilən sorğular bloklanıb.','Processing…' => 'İşlənir…','Something went wrong. Please try again.' => 'Xəta baş verdi. Zəhmət olmasa, yenidən cəhd edin.','Activate plugin' => 'Plagini aktivləşdirin','Fluid Checkout PRO - The complete checkout package' => 'Maye Checkout PRO - Tam ödəmə paketi','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Bütün PRO xüsusiyyətləri + bütün əlavələr, bir qiymət. Dizayn şablonları, optimallaşdırılmış səbət və sifariş qəbulu səhifələri, hesab uyğunluğu və daha çox şey.','Optimized order pay page' => 'Optimallaşdırılmış sifariş ödəmə səhifəsi','Express checkout buttons from supported payment methods' => 'Dəstəklənən ödəniş üsullarından ekspress ödəmə düymələri','Delayed account creation' => 'Gecikmiş hesab yaradılması','Address autocomplete with Google Maps APIs' => 'Google Xəritə API-ləri ilə ünvanın avtomatik tamamlanması','Multiple saved addresses with the address book' => 'Ünvan kitabçası ilə birdən çox ünvan saxlanıldı','EU-VAT assistant' => 'AB-ƏDV köməkçisi','Hide this section' => 'Bu bölməni gizlət','Learn more' => 'Daha çox məlumat əldə edin','Get early access' => 'Erkən giriş əldə edin','Activate add-on' => 'Əlavəni aktivləşdirin','Get more out of your checkout journey' => 'Kassa səyahətinizdən daha çox faydalanın','Test API key' => 'Test API açarı','Guided setup' => 'Rəhbərli quraşdırma','Options' => 'Seçimlər','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">Kassa seçimlərində</a> düzeni və dizaynı təyin edin.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Qonaqların ödənişini aktivləşdirin və/və ya <a href="%s">müştəri hesabı parametrlərini</a> nəzərdən keçirin.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Optimallaşdırılmış <a href="%1$s">səbət</a> , <a href="%2$s">təşəkkür</a> və <a href="%3$s">sifariş ödəmə</a> səhifələrini aktivləşdirin.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google Xəritələrdən <a href="%s">ünvanın avtomatik tamamlanmasını</a> aktivləşdirin.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">Ünvan kitabçası</a> ilə birdən çox yadda saxlanılan ünvanı aktivləşdirin.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Mövzu və ya quraşdırdığınız digər plaginlər üçün <a href="%s">inteqrasiya seçimlərinin</a> olub olmadığını yoxlayın.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Daha sürətli dəstək alın və uyğunluğu təkmilləşdirməyimizə və təsirləri ölçməyimizə kömək edin. Alət parametrlərindən <a href="%s">istifadə izləməsini aktivləşdirin</a> .','Missing settings tab.' => 'Ayarlar sekmesi yoxdur.','Getting started' => 'Başlamaq','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Əla! Ödəniş səhifəniz artıq Fluid Checkout-da işləyir.</strong> Başlamaq üçün bir neçə addım:','Completed' => 'Tamamlandı','Preview report data' => 'Hesabat məlumatlarına önizləmə','Send now' => 'İndi göndərin','Auto-detect' => 'Avtomatik aşkarlama','Afrikaans' => 'Afrikaans','Albanian' => 'Alban','Amharic' => 'Amhar','Arabic' => 'Ərəb','Armenian' => 'Erməni','Azerbaijani' => 'Azərbaycan dili','Basque' => 'Bask','Belarusian' => 'Belarus dili','Bengali' => 'Benqal dili','Bosnian' => 'Bosniya','Bulgarian' => 'Bolqar','Burmese' => 'Birma','Catalan' => 'Katalan dili','Chinese' => 'Çin dili','Chinese (Simplified)' => 'Çin (Sadələşdirilmiş)','Chinese (Hong Kong)' => 'Çin (Honkonq)','Chinese (Traditional)' => 'Çin (Ənənəvi)','Croatian' => 'Xorvat','Czech' => 'Çex dili','Danish' => 'Danimarka','Dutch' => 'Hollandca','English' => 'İngilis dili','English (Australian)' => 'İngilis (Avstraliya)','English (Great Britain)' => 'İngilis dili (Böyük Britaniya)','Estonian' => 'Eston dili','Farsi' => 'Farsca','Finnish' => 'Fin','Filipino' => 'Filippin','French' => 'Fransız dili','French (Canadian)' => 'Fransız (Kanada)','Galician' => 'Qalisian','Georgian' => 'Gürcü','German' => 'Alman','Greek' => 'Yunan','Gujarati' => 'Qucarat','Hebrew' => 'İvrit dili','Hindi' => 'Hind dili','Hungarian' => 'Macar','Icelandic' => 'İsland dili','Indonesian' => 'İndoneziya dili','Italian' => 'İtalyan','Japanese' => 'Yapon','Kannada' => 'Kannada','Kazakh' => 'Qazax','Khmer' => 'Khmer','Korean' => 'Koreya dili','Kyrgyz' => 'Qırğız','Lao' => 'Laos','Latvian' => 'Latış dili','Lithuanian' => 'Litva','Macedonian' => 'Makedoniya','Malay' => 'Malay','Malayalam' => 'Malayalam','Marathi' => 'Marathi','Mongolian' => 'Monqol','Nepali' => 'Nepal dili','Norwegian' => 'Norveç','Polish' => 'Polşa','Portuguese' => 'Portuqal dili','Portuguese (Brazil)' => 'Portuqal (Braziliya)','Portuguese (Portugal)' => 'Portuqal (Portuqaliya)','Punjabi' => 'Pəncab','Romanian' => 'Rumın','Russian' => 'Rusca','Serbian' => 'Serb dili','Sinhalese' => 'Sinhal dili','Slovak' => 'Slovak dili','Slovenian' => 'Slovencə','Spanish' => 'İspan dili','Spanish (Latin America)' => 'İspan (Latın Amerikası)','Swahili' => 'Suahili','Swedish' => 'İsveç','Tamil' => 'Tamil','Telugu' => 'Teluqu','Thai' => 'Tayland','Turkish' => 'Türkcə','Ukrainian' => 'Ukrayna','Urdu' => 'Urdu','Vietnamese' => 'Vyetnam','Zulu' => 'Zulu','Google address autocomplete' => 'Google ünvanının avtomatik tamamlanması','Google Places API version' => 'Google Places API versiyası','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API-nin hansı versiyasından istifadə edəcəyinizi seçin. Ən qısa müddətdə yeni Places API-yə keçməyi tövsiyə edirik.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => '1 mart 2025-ci il tarixindən etibarən &quot;Places API (Yeni)&quot; istifadə etməyi tövsiyə edirik. Google &quot;Places API (Köhnə)&quot; versiyasını Köhnə statusuna keçirəcək, yəni artıq bu xidməti yeni API açarları üçün aktivləşdirə bilməyəcəksiniz və API-nin həmin versiyası nəticədə artıq mövcud olmayacaq. Artıq Köhnə API istifadə edən mövcud hesablar fasiləsiz işləməyə davam edə bilər.','(Recommended)' => '(Tövsiyə olunur)','Google API key' => 'Google API açarı','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Google API açarınızı yapışdırın və test düyməsini istifadə edərək bu veb sayt üçün işlədiyini təsdiqləyin. Açarın etibarlı olduğundan və domeniniz üçün icazə verildiyindən əmin olun, əks halda ünvan sahəsi bloklana bilər və müştərilərin sifarişlərini yerinə yetirməsinə mane ola bilər.','Enable Google address autocomplete' => 'Google ünvanının avtomatik tamamlanmasını aktivləşdirin','Enable address autocompletion using the Google Maps APIs.' => 'Google Xəritə API-lərindən istifadə edərək ünvanın avtomatik tamamlanmasını aktivləşdirin.','Google API language' => 'Google API dili','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Bu dil Google Places API ünvan təkliflərini göstərmək üçün istifadə olunacaq və ünvanlar da bu dildə avtomatik olaraq tamamlanacaq.','Result types' => 'Nəticə növləri','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Adətən daha yaxşı uyğunluq nəticələri verən istənilən nəticəni qəbul etmək üçün boş buraxın. <a href="%s" target="_blank">Daha ətraflı məlumat üçün sənədlərə baxın</a> .<br> Ünvan avtomatik tamamlama sahələrində qaytarmaq üçün 5 növə qədər ünvan axtarışı nəticəsi seçin.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Dəstəklənən növlər</a> haqqında daha çox məlumat əldə etmək üçün Google Xəritə sənədlərinə daxil olun.','Result types (Legacy API)' => 'Nəticə növləri (Köhnə API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (Legacy) istifadə edərkən hansı növ ünvan axtarış nəticələrini qaytarmaq lazımdır.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">Dəstəklənən növlər</a> haqqında daha çox məlumat əldə etmək üçün Legacy Google Places API sənədlərinə baxın.','Company fields' => 'Şirkət sahələri','Enable autocomplete for the company name if available' => 'Mövcuddursa, şirkət adı üçün avtomatik tamamlamanı aktivləşdirin','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google Xəritə API-lərindən qaytarıldıqda şirkət sahəsinin şirkət adı məlumatları ilə avtomatik tamamlanmasını aktivləşdirin.','Business search' => 'Biznes axtarışı','Enable search for businesses in the company field' => 'Şirkət sahəsində biznes axtarışını aktivləşdirin','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Şirkət sahəsinə yazarkən bizneslə əlaqəli ünvanların təklifini aktivləşdirin, sonra təkliflərdən biznes seçildikdə bütün ünvan sahələrini avtomatik doldurun.','Company result types' => 'Şirkət nəticə növləri','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Avtomatik doldurma şirkət sahələrində qaytarmaq üçün 5 növə qədər ünvan axtarışı nəticəsi seçin.<br> Tövsiyə olunan dəyər əksər biznes növlərini əhatə edən <code>establishment</code> .<br> Bizneslərlə əlaqəli olmayan nəticələr də daxil olmaqla, istənilən növ nəticəni qəbul etmək üçün boş buraxın.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Dəstəklənən növlər</a> haqqında daha çox məlumat əldə etmək üçün Google Xəritə sənədlərinə daxil olun.','Google logo' => 'Google loqosu','Show text and logo "Powered by Google"' => '&quot;Google tərəfindən dəstəklənir&quot; mətni və loqotipi göstər','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'İşarələndikdə, ünvan avtomatik tamamlama təklifləri qutusunun aşağı hissəsində &quot;Google tərəfindən dəstəklənir&quot; mətni və loqotipi görünəcək.','Brasil API address autocomplete' => 'Braziliya API ünvanının avtomatik tamamlanması','Brasil API' => 'Braziliya API-si','Enable Brasil API address autocomplete for CEP fields' => 'CEP sahələri üçün Brasil API ünvanının avtomatik tamamlanmasını aktivləşdirin','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/Poçt kodu sahəsini istifadə edərək ünvanları əldə etmək və avtomatik doldurmaq üçün Brasil API-dən istifadə edin. Yalnız Braziliya ünvanları üçün uyğundur.','API version' => 'API versiyası','Choose which version of the Brasil API CEP method to use.' => 'Brasil API CEP metodunun hansı versiyasından istifadə edəcəyinizi seçin.','Address book migration' => 'Ünvan kitabçası miqrasiyası','WooCommerce addresses' => 'WooCommerce ünvanları','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce-dən mövcud çatdırılma və ödəniş ünvanlarını müştərilərin ünvan kitabına kopyalayın.','Enable the address book feature' => 'Ünvan kitabçası funksiyasını aktivləşdirin','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Müştərilərə birdən çox ünvanı saxlamağa və çatdırılma və ödəniş üçün istifadə ediləcək standart ünvanı təyin etməyə icazə verin.','Address labels' => 'Ünvan etiketləri','Allow customers to add a custom label for each address' => 'Müştərilərə hər ünvan üçün xüsusi etiket əlavə etməyə icazə verin','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Ünvan etiketləri müştərilərin yadda saxlanılan ünvanlarını (məsələn: &quot;Ana Evi&quot;) ayırd etməsini asanlaşdırır. Ünvan etiketləri müştərilər üçün gizlidir və sifariş təfərrüatları səhifəsində və ya fakturalarda göstərilməyəcək və ya çap olunmayacaq.','Display layout' => 'Ekran düzeni','Choose how saved addresses are displayed at checkout and on the cart.' => 'Yadda saxlanılan ünvanların ödəniş zamanı və səbətdə necə göstəriləcəyini seçin.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Kassada və səbətdə keçərlidir. Hesab səhifəsində yadda saxlanılan ünvanlar həmişə kartların düzülüşündən istifadə edir.','Address cards' => 'Ünvan kartları','Address list' => 'Ünvan siyahısı','Dropdown field' => 'Açılan menyu sahəsi','Address search' => 'Ünvan axtarışı','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Müştərinin ən azı bu sayda yadda saxlanılan ünvanı olduqda, ön tərəfdə ünvan axtarış filtrini göstərin.','Not used when display layout is set to dropdown field.' => 'Ekran düzeni açılan sahəyə təyin edildikdə istifadə edilmir.','Addresses' => 'Ünvanlar','Enable cart page optimizations to see more options' => 'Daha çox seçim görmək üçün səbət səhifəsi optimallaşdırmalarını aktivləşdirin','Sticky order summary' => 'Yapışqan sifariş xülasəsi','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Səbət səhifəsində kupon kodları bölməsinin göstəriləcəyi yeri seçin. Yalnız AJAX səbəti aktiv olduqda və WooCommerce parametrlərində kupon kodlarının istifadəsi aktiv olduqda tətbiq olunur.','Layout of cross-sell' => 'Çarpaz satışın düzülüşü','Cross-sells displayed' => 'Çarpaz satışlar nümayiş etdirilib','Items' => 'Əşyalar','Cart page optimization' => 'Səbət səhifəsinin optimallaşdırılması','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Səbətinizə ödəniş zamanı istifadə etdiyiniz kimi eyni aydın, konversiyaya yönəlmiş tərtibat verin.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Ardıcıl bir alış-veriş səyahəti üçün səbətin düzülüşünü ödəmə səhifəsi ilə uyğunlaşdırın.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Səbəti həmişə arxa planda yeniləyin, miqdar dəyişdikdə səhifənin tam yenidən yüklənməsinə ehtiyac qalmasın.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Kupon kodlarını, çatdırılmanı və çarpaz satışları ən yaxşı çevirmə imkanları olan yerlərdə yerləşdirin.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Sürüşdürərkən sifariş xülasəsini görünən saxlayın və alıcıların əminliyə ehtiyac duyduğu yerlərdə etibar simvolları əlavə edin.','Columns' => 'Sütunlar','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Sifariş mərhələləri, sifariş xülasəsi və digər bölmələr üçün ümumi üslublar. Digər sifariş, səbət, təşəkkür (sifariş qəbul edildi) və sifariş səhifələrinə aiddir.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;Bölün&quot;</em> dizayn şablonu ilə <em>&quot;1 sütun&quot;</em> düzenindən istifadə edərkən, sağ sütun yalnız səhifə yan çubuğu vidjet sahəsi aktiv olduqda göstərilir (Yan çubuğu yoxlayın, Səbət yan çubuğu və ya Sifariş alınan yan çubuğu). Əks halda, səhifə Bölünmüş üslublarla tək sütun kimi qalır.','Split column background' => 'Sütun arxa planını ayırın','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => '&quot;Bölünmüş dizayn&quot; ikinci sütunu üçün fon rəngi seçin. Sifariş xülasəsinin fon rəngindən istifadə etmək üçün boş saxlayın.','Page templates' => 'Səhifə şablonları','Checkout template' => 'Kassa şablonu','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Kassada diqqəti yayındıran amillərin sayını azaltmaq üçün tövsiyə olunur. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Səbətdən imtina ilə bağlı araşdırmanı oxuyun</a> .','Sticky progress bar' => 'Yapışqan irəliləyiş paneli','Progress bar style' => 'Tərəqqi paneli stili','Order totals' => 'Sifarişlərin cəmi','Background color' => 'Arxa fon rəngi','Action link' => 'Fəaliyyət linki','Mobile order summary' => 'Mobil sifariş xülasəsi','Mobile initial state' => 'Mobil ilkin vəziyyət','Enable editing cart items at checkout' => 'Səbət elementlərini ödəniş zamanı redaktə etməyi aktivləşdirin','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Müştərilərə məhsul miqdarını dəyişdirməyə və ya məhsulları birbaşa ödəmə səhifəsində silməyə icazə verin.','Cart item errors' => 'Səbət elementi xətaları','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Yalnız kupon kodu ödəniş və ya səbət səhifələrində ayrıca bölmə kimi göstərildikdə və WooCommerce parametrlərində kupon kodlarının istifadəsi aktiv olduqda tətbiq olunur.','Coupon codes position' => 'Kupon kodları mövqeyi','Apply coupon button' => 'Kupon tətbiq et düyməsi','Select style of the "apply coupon" button.' => '&quot;Kupon tətbiq et&quot; düyməsinin stilini seçin.','Address line 2' => 'Ünvan sətri 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Bu parametr Sifariş və Yerli götürmə bölmələri arasında paylaşılır. Yerli götürmə bölməsində, Göndərmə/Götürmə seçicisinin göndərmə metodu bölməsinin içərisində (ünvandan əvvəl) və ya ayrıca bölmə (sonra) kimi göstərilib-göstərilmədiyini də müəyyən edir.','Customer accounts' => 'Müştəri hesabları','Guest checkout' => 'Qonaq kassası','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Qonaq hesabı, giriş və hesab yaratma seçimləri WooCommerce Hesab parametrləri səhifəsindəndir. Bunlar sizin rahatlığınız üçün burada idarə olunur və buna görə də hər parametr profili üçün fərqli dəyərlərdən istifadə edə bilərsiniz.','Allow customers to checkout without an account' => 'Müştərilərə hesab açmadan ödəniş etməyə icazə verin','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'Müştərilərdən ödəniş zamanı hesab yaratmaları və ya daxil olmaları istənməməsi üçün <strong>tövsiyə olunur</strong> , çünki bu, konversiya nisbətlərini aşağı sala bilər.','When disabled, customers must log in or create an account to complete the purchase.' => 'Deaktiv edildikdə, müştərilər alış-verişi tamamlamaq üçün daxil olmalı və ya hesab yaratmalıdırlar.','Login at checkout' => 'Kassada daxil olun','Enable log-in during checkout' => 'Ödəniş zamanı girişi aktivləşdirin','Show a link for returning customers to log in from the checkout page.' => 'Qayıdan müştərilərin ödəniş səhifəsindən daxil olması üçün keçid göstərin.','Account creation' => 'Hesab yaradılması','Allow customers to create an account during checkout' => 'Müştərilərə ödəmə zamanı hesab yaratmağa icazə verin','Customers can create an account before placing their order.' => 'Müştərilər sifariş verməzdən əvvəl hesab yarada bilərlər.','Allow customers to create an account from the My account page' => 'Müştərilərə Hesabım səhifəsindən hesab yaratmağa icazə verin','Customers can register a new account from the My account page.' => 'Müştərilər &quot;Hesabım&quot; səhifəsindən yeni hesab qeydiyyatdan keçirə bilərlər.','Username' => 'İstifadəçi adı','Generate from customer\'s name' => 'Müştərinin adından yaradın','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'Müştərilərdən ödəniş zamanı istifadəçi adı seçmələri istənməməsi <strong>tövsiyə olunur</strong> , çünki bu, konversiya nisbətlərini aşağı sala bilər.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'İstifadəçi adı müştərinin adından və ya ad istifadə edilə bilmədikdə elektron poçt ünvanından yaradılır.','Password' => 'Şifrə','Send password setup link' => 'Şifrə quraşdırma linkini göndərin','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'Müştərilərdən ödəniş zamanı parol təyin etmələri istənməməsi üçün <strong>tövsiyə olunur</strong> , çünki bu, konversiya nisbətlərini aşağı sala bilər.','Customers receive an email to create their password securely.' => 'Müştərilər şifrələrini təhlükəsiz şəkildə yaratmaq üçün elektron poçt alırlar.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Qeydiyyatdan keçmiş müştərilərin hesaba daxil olmadan ödənişi tamamlamasına icazə verin və əlaqə məlumatları uyğun gəldikdə sifarişi mövcud hesabları ilə əlaqələndirin.','Existing account message' => 'Mövcud hesab mesajı','Let customers create an account after placing their order, from the thank you page.' => 'Müştərilərin təşəkkür səhifəsindən sifariş verdikdən sonra hesab yaratmasına icazə verin.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Bu bölmədəki seçimlər qonaq çıxışı və hesab uyğunluğu aktiv olduqda mövcuddur. Gecikmiş hesab yaradılmasını konfiqurasiya etmək üçün yuxarıdakı hər iki funksiyanı aktivləşdirin.','Enable delayed account creation' => 'Gecikmiş hesab yaratmağı aktivləşdirin','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Qonaq çıxışı və hesab uyğunluğu aktiv olduqda gecikmiş hesab yaradılmasını aktivləşdirin.','Section position' => 'Bölmə mövqeyi','Before customer details section' => 'Müştəri məlumatları bölməsindən əvvəl','After customer details section' => 'Müştəri Məlumatlarından Sonrakı Bölmə','Account creation benefits' => 'Hesab yaratma üstünlükləri','Leaving the field empty will display the default text.' => 'Sahəni boş qoymaq standart mətni göstərəcək.','Inline buttons' => 'Sətir içi düymələr','Required fields' => 'Tələb olunan sahələr','Enable gift message fields at checkout' => 'Ödəniş zamanı hədiyyə mesajı sahələrini aktivləşdirin','Expanded gift message' => 'Genişləndirilmiş hədiyyə mesajı','Display gift message field always expanded' => 'Hədiyyə mesajı sahəsini göstər həmişə genişləndirin','Gift message in order details' => 'Sifariş təfərrüatları ilə bağlı hədiyyə mesajı','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Bu bölmədə hazırda heç bir inteqrasiya mövcud deyil. Hər bir plagin və mövzu ilə əlaqəli seçimlər yalnız həmin plagin və ya mövzu aktivləşdirildikdə burada görünəcək.','Phone fields' => 'Telefon sahələri','Field visibility' => 'Sahə görünürlüyü','Field position' => 'Sahə mövqeyi','Phone country code & validation' => 'Telefon ölkə kodu və təsdiqləmə','Country' => 'Ölkə','Enable country on phone fields' => 'Telefon sahələrində ölkəni aktivləşdirin','Filter countries for shipping or billing' => 'Göndərmə və ya faktura üçün ölkələri filtrləyin','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Hər telefon sahəsində ölkə seçicisini mağazanızda çatdırılma və ya ödəniş üçün icazə verilən ölkələrlə məhdudlaşdırın.','Validation' => 'Doğrulama','Enable simple validation based on country rules' => 'Ölkə qaydalarına əsaslanan sadə təsdiqləməni aktivləşdirin','Checks that the phone number is valid for the selected country, including country code and length.' => 'Telefon nömrəsinin, ölkə kodu və uzunluğu daxil olmaqla, seçilmiş ölkə üçün etibarlı olduğunu yoxlayır.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Nömrənin seçilmiş ölkə üçün etibarlı mobil, sabit xətt və ya digər qəbul edilmiş növ olduğunu daha ciddi şəkildə yoxlayın. Bəzi etibarlı nömrələr rədd edilə bilər.','Validation types' => 'Doğrulama növləri','Placeholders' => 'Yer tutucular','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Hazırda idarə etmək üçün lisenziya açarı yoxdur. Lisenziyalı Fluid Checkout plagini və ya əlavəsi aktiv olduqda lisenziya açarları burada görünəcək.','Default delivery type' => 'Standart çatdırılma növü','Choose which delivery type will be selected by default.' => 'Varsayılan olaraq hansı çatdırılma növünün seçiləcəyini seçin.','Shipping zone fields' => 'Göndərmə zonası sahələri','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Yerli çatdırılma zonası filtr sahələri üçün hansı sahələrin göstəriləcəyini seçin. Bütün mövcud seçimləri göstərmək üçün boş saxlayın.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Bu sahələr yerli çatdırılma üsulları üçün filtr kimi göstəriləcək. Uyğun plaginlərin düzgün işləməsini tələb etdiyi təqdirdə, bəzi sahələr burada seçilmədikdə də ödəniş zamanı görünə bilər.','Order shipping address' => 'Sifarişin çatdırılma ünvanı','Order pay page optimization' => 'Sifariş ödənişi səhifəsinin optimallaşdırılması','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Ödənilməmiş sifarişlərə ödənişlə eyni aydın, konversiyaya yönəlmiş tərtibat verin.','Optimize the layout of the order pay page for orders pending payment.' => 'Ödənişi gözləyən sifarişlər üçün sifariş ödəniş səhifəsinin düzenini optimallaşdırın.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Ardıcıl bir alış-veriş səyahəti üçün sifariş ödəmə təcrübənizi kassanızla uyğunlaşdırın.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Alıcıların ödəniş etməzdən əvvəl əminliyə ehtiyac duyduqları yerlərdə etibar simvolları və nişanlar əlavə edin.','Thank you page optimization' => 'Səhifə optimallaşdırması üçün təşəkkürlər','Make the thank you page and order details clearer for customers after they buy.' => 'Müştərilər alış-veriş etdikdən sonra təşəkkür səhifəsini və sifariş məlumatlarını daha aydın şəkildə bildirin.','Optimize the thank you page and account order details with a clearer layout.' => 'Təşəkkür səhifəsini və hesab sifarişi məlumatlarını daha aydın bir tərtibatla optimallaşdırın.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Sifarişin statusunun gedişatını, hərəkətləri, yükləmələri və qeydləri məntiqli olduqları yerdə göstərin.','Customize order details sections on email notifications.' => 'E-poçt bildirişlərində sifariş təfərrüatları bölmələrini fərdiləşdirin.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Alış-verişdən sonra alıcıların arxayınlığa ehtiyacı olduğu yerlərdə etibar simvolları və nişanlar əlavə edin.','Email notifications' => 'E-poçt bildirişləri','Enable thank you page and order details optimizations to see more options' => 'Daha çox seçim görmək üçün təşəkkür səhifəsini və sifariş detallarının optimallaşdırılmasını aktivləşdirin','Use wide layout on thank you page' => 'Təşəkkür səhifəsində geniş layoutdan istifadə edin','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Bu seçimlər təşəkkür səhifəsinə, hesab səhifələrində və e-poçt bildirişlərində sifariş təfərrüatlarına baxmağa təsir göstərir.','Save settings' => 'Parametrləri yadda saxla','Docs' => 'Sənədlər','Cart' => 'Səbət','Thank you' => 'Təşəkkür edirəm','Address autocomplete' => 'Ünvan avtomatik tamamlanır','Trust badges' => 'Etibar nişanları','You do not have permission to save these settings.' => 'Bu parametrləri yadda saxlamaq üçün icazəniz yoxdur.','Invalid save request.' => 'Yanlış saxlama sorğusu.','Your settings have been saved.' => 'Parametrləriniz yadda saxlanıldı.','Saving...' => 'Yadda saxlanılır...','Settings could not be saved. Please try again.' => 'Parametrlər yadda saxlanıla bilmədi. Yenidən cəhd edin.','Dismiss notice' => 'Bildirişi rədd edin','Open settings menu' => 'Ayarlar menyusunu açın','Close settings menu' => 'Ayarlar menyusunu bağlayın','Preview' => 'Önizləmə','Expand preview' => 'Önizləməni genişləndirin','Collapse preview' => 'Önizləməni yığcamlaşdırın','Show header and footer' => 'Başlıq və altbilgini göstər','Hide header and footer' => 'Başlıq və altbilgini gizlət','Page preview' => 'Səhifə önizləməsi','Preview viewport' => 'Görünüş portuna ön baxış','Tablet' => 'Planşet','Desktop' => 'Masaüstü','Preview width' => 'Önizləmə eni','Decrease width' => 'Eni azaldın','Preview width in pixels' => 'Önizləmə eni piksellə','Increase width' => 'Genişliyi artırın','Preview as' => 'Önizləmə kimi','Guest' => 'Qonaq','Logged in' => 'Daxil olmusunuz','Preview page' => 'Önizləmə səhifəsi','Expand preview for a closer look' => 'Daha yaxından baxmaq üçün önizləməni genişləndirin','Available with %s.' => '%s ilə mövcuddur.','Turn them on' => 'Onları yandırın','Optimizations for this page are turned off. %s to preview the page.' => 'Bu səhifə üçün optimallaşdırmalar deaktiv edilib. Səhifəni önizləmək üçün %s.','%s preview' => '%s önizləməsi','Isolated session · nothing is saved' => 'Təcrid olunmuş sessiya · heç nə yadda saxlanılmayıb','Usage tracking' => 'İstifadə izlənməsi','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Fluid Checkout-un uyğunluğu yaxşılaşdırmasına kömək etmək üçün həssas olmayan sayt mühiti hesabatları göndərin. Aşağıdakı seçimlərdə aktivləşdirilənə qədər hesabatlar göndərilmir.','Send usage tracking reports to Fluid Checkout' => 'İstifadə izləmə hesabatlarını Fluid Checkout-a göndərin','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Bu hesabatlar saytınız üçün uyğunluğu və dəstəyi təkmilləşdirməyə kömək edir və aktiv olduqda həftəlik olaraq göndərilir.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Hesabatlara heç bir müştəri, admin istifadəçisi və ya digər həssas məlumatlar daxil edilməyib.','Basic environment info' => 'Əsas ətraf mühit məlumatları','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress, PHP, WooCommerce, mövzu və plagin siyahısı məlumatları. Hesabat aktiv olduqda həmişə daxil edilir. Saytınızın hansı mühitdə işlədiyini anlamağımıza kömək edir.','Plugin settings' => 'Plugin parametrləri','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Dəstək sorğularına kömək etmək üçün Fluid Checkout plagini parametrlərini göndərir və plaginlərimizdən necə istifadə etdiyinizi anlamağımıza kömək edir.','Coming soon' => 'Tezliklə','Sales metrics' => 'Satış ölçümləri','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Fluid Checkout quraşdırılmazdan bir il əvvəl bu günə qədər aylıq sifariş sayı və ümumi satışlar. Quraşdırılmış plaginlərimizlə daha çox pul qazanıb-qazanmadığınızı anlamağımıza kömək edir. Heç bir müştəri və ya istifadəçi məlumatları göndərilmir.','Utilities' => 'Kommunal xidmətlər','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> əvəzinə <code>TomSelect</code> açılan komponentlərindən istifadə edin','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect, Select2-dən daha az səhvə meylli olan daha sadə açılan menyu seçim komponentidir və eyni funksionallığı təklif edir.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Kiçik cihazlarda forma sahələri ilə qarşılıqlı əlaqədə olarkən avtomatik olaraq böyüdülməməsi üçün bu plagin tərəfindən optimallaşdırılmış səhifələrdə forma sahələri daxilindəki şrift ölçüsünü 16 pikselə təyin edir.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Şrift ölçüsü 16 pikseldən kiçik olduqda, Safari və digər brauzerlər mətni oxumağı asanlaşdırmaq üçün mobil cihazlarda avtomatik olaraq böyüdə bilər.','Enable script processing tracking on the browser console.' => 'Brauzer konsolunda skript emalının izlənilməsini aktivləşdirin.','Unminified assets' => 'Minimallaşdırılmamış aktivlər','Google Maps scripts' => 'Google Xəritə skriptləri','Do not remove duplicate Google Maps scripts' => 'Dublikat Google Xəritə skriptlərini silməyin','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Aktivləşdirildikdə, səhvlərə və performans problemlərinə səbəb ola biləcək dublikat Google Xəritə skriptləri SİLİNMƏYƏCƏK. Bu seçimdən yalnız problemlərin aradan qaldırılması zamanı istifadə edin.','Widget areas' => 'Vidjet sahələri','Last step on mobile' => 'Mobil cihazlarda son addım','Display widgets only at last step on mobile' => 'Mobil cihazlarda yalnız son addımda vidjetləri göstərin','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Mobil cihazlarda yalnız son ödəniş mərhələsinə baxarkən ödəniş etimad nişanı vidjetlərini göstərin','Standard' => 'Standart','VAT number field' => 'ƏDV nömrəsi sahəsi','Add a VAT number field to the billing form.' => 'Ödəniş formasına ƏDV nömrəsi sahəsi əlavə edin.','Field label' => 'Sahə etiketi','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'ƏDV nömrəsi sahəsinin etiketini (yəni, ƏDV nömrəsi) təyin edin. Çoxdilli veb saytlarda bu sahəni boş qoymaq və orijinal sətri tərcümə etmək daha yaxşıdır.','VAT Number' => 'ƏDV Nömrəsi','EU-VAT' => 'AB-ƏDV','Enable the VAT number field to see more options' => 'Daha çox seçim görmək üçün ƏDV nömrəsi sahəsini aktivləşdirin','VAT validation' => 'ƏDV təsdiqlənməsi','Validate VAT number field for EU-VAT during checkout' => 'Ödəniş zamanı AB-ƏDV üçün ƏDV nömrəsi sahəsini təsdiqləyin','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Təqdim edilən ƏDV Nömrəsinin Avropa VIES Verilənlər Bazasında (ƏDV Məlumat Mübadiləsi Sistemi) qeydiyyatdan keçmiş etibarlı ƏDV nömrəsi olub olmadığını yoxlayır.','Shop VAT number' => 'Mağaza ƏDV nömrəsi','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Mağazanın Aİ-ƏDV təsdiqlənməsini tələb etmək üçün istifadə edilən və fakturalarda çap olunmuş ƏDV nömrəsi.<br> <strong>Mağaza ƏDV nömrənizi əlavə etməyinizi tövsiyə edirik,</strong> əks halda VIES məsləhətləşmə nəticələri mühasibat uçotu məqsədləri üçün etibarlı olmaya bilər.<br> Yəni: <code>ATU99999999</code> və ya <code>EE999999999</code> .','Reverse charge' => 'Tərs yük','Apply reverse charge mechanism' => 'Əks yükləmə mexanizmini tətbiq edin','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Vergi dərəcəsini sıfıra təyin edin və müştərinin ƏDV nömrəsi etibarlı olduqda fakturalarda &quot;Tərs ödəniş&quot; yazısını göstərin. Mağazanın ölkəsindən asılı olaraq fərqli bir &quot;Tərs ödəniş&quot; mətni tələb oluna bilər.','Same country' => 'Eyni ölkə','Apply reverse charge mechanism for transactions in the shop country:' => 'Mağaza ölkəsindəki əməliyyatlar üçün tərs ödəniş mexanizmini tətbiq edin:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Mağaza ilə eyni ölkədəki şirkətlər arasında əməliyyatlar üçün tərs ödəniş mexanizminin tətbiqini təmin edir.','Reverse charge exceptions' => 'Əks ödəniş istisnaları','Select additional countries to skip applying the reverse charge mechanism.' => 'Əks ödəniş mexanizminin tətbiqini atlamaq üçün əlavə ölkələr seçin.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Hətta etibarlı ƏDV nömrəsi təqdim edildikdə belə, bu ölkələrdən gələn sifarişlərdən vergi tutulacaq.','Reverse charge label on invoices' => 'Fakturalardakı tərs ödəniş etiketi','Set the label of "reverse charge" on the checkout page and order details.' => 'Sifariş səhifəsində və detallarında &quot;əks ödəniş&quot; etiketini təyin edin.','Reverse charge text on invoices' => 'Fakturalardakı tərs ödəniş mətni','Set the label of "reverse charge" text on invoices.' => 'Fakturalarda &quot;tərs ödəniş&quot; mətni etiketini təyin edin.','Tax to be paid on reverse charge basis' => 'Vergi geri ödəmə əsasında ödəniləcək','Company name' => 'Şirkət adı','Autocomplete company name from VAT number' => 'ƏDV nömrəsindən şirkət adını avtomatik tamamlayın','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Müştəri tərəfindən təqdim edilən etibarlı ƏDV nömrəsinə əsasən faktura şirkətinin adını doldurun.','Company name editing' => 'Şirkət adının redaktəsi','Allow editing of auto-filled company name' => 'Avtomatik doldurulmuş şirkət adının redaktəsinə icazə verin','When enabled, customers can change the company name associated with the provided VAT number.' => 'Aktivləşdirildikdə, müştərilər təqdim edilmiş ƏDV nömrəsi ilə əlaqəli şirkət adını dəyişə bilərlər.','EU-VAT for digital goods' => 'Rəqəmsal mallar üçün Aİ-ƏDV','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '1 yanvar 2015-ci il tarixindən etibarən rəqəmsal mallarla bağlı Aİ ƏDV qaydalarına yalnız B2C əməliyyatlarına təsir edən dəyişikliklər edilib. Rəqəmsal mallar üzrə ƏDV müştərinin yerləşdiyi yerə əsasən hesablanmalı və bunun sübutları (IP ünvanı və ödəniş ünvanı) toplanmalıdır.','Tax classes for digital goods' => 'Rəqəmsal mallar üçün vergi sinifləri','Select some tax classes' => 'Bəzi vergi siniflərini seçin','Location evidence' => 'Yer sübutu','Collect customer\'s location evidence' => 'Müştərinin yerləşmə sübutlarını toplayın','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP ünvanını saxlayır və müştərinin ödəniş ünvanı ilə uyğunluğunu yoxlayır. Müştərilər ödəniş ünvanındakı ölkə və IP uyğun gəlmirsə, ödəniş səhifəsindəki onay qutusunu işarələyərək ödəniş ünvanlarını təsdiqləməlidirlər.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Bu seçim Maye Ödənişində idarə olunur. <a href="%s">Onu Müştəri hesabları parametrlərində dəyişdirin</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Bu seçim Maye Ödənişi bölməsində idarə olunur. Onu Maye Ödənişi &gt; Müştəri hesabları bölməsində dəyişdirin.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Bu seçim Fluid Checkout-da idarə olunur. Fluid Checkout aktivləşdirildikdə çatdırılma təyinatı həmişə &quot;Müştəri çatdırılma ünvanı üçün standart&quot; olaraq təyin olunur. Müştərilər yenə də ödəniş zamanı fərqli çatdırılma və faktura ünvanları təqdim edə bilərlər.<br><br> Standart ödəniş ünvanının çatdırılma ünvanı ilə eyni olmasını təyin etmək üçün seçim <a href="%s">Maye Ödəniş parametrlərində</a> mövcuddur.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Bu seçim Fluid Checkout-da idarə olunur. Fluid Checkout aktivləşdirildikdə çatdırılma təyinatı həmişə &quot;Müştəri çatdırılma ünvanı üçün standart&quot; olaraq təyin olunur. Müştərilər yenə də ödəniş zamanı fərqli çatdırılma və faktura ünvanları təqdim edə bilərlər.<br><br> Varsayılan ödəniş ünvanının çatdırılma ünvanı ilə eyni olmasını təyin etmək üçün bir seçim WooCommerce &gt; Parametrlər &gt; Maye Ödənişi bölməsində mövcuddur.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Bu parametrlər WP Admin &gt; Maye Ödənişi &gt; Parametrlər bölməsinə köçürülüb.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Bu WooCommerce Parametrləri sekmesi köhnəlib və Fluid Checkout 6.0-da silinəcək.','Go to settings page' => 'Ayarlar səhifəsinə keçin','Hide this tab permanently' => 'Bu sekmeyi birdəfəlik gizlədin','Site report preview' => 'Sayt hesabatına ön baxış','This is the data that would be included in the next site environment report based on your current settings.' => 'Bu, cari parametrlərinizə əsasən növbəti sayt mühiti hesabatına daxil ediləcək məlumatlardır.','Loading report preview...' => 'Hesabat önizləməsi yüklənir...','Could not load the site report preview. Try again.' => 'Sayt hesabatının önizləməsini yükləmək mümkün olmadı. Yenidən cəhd edin.','Could not send the site report. Try again.' => 'Sayt hesabatını göndərmək mümkün olmadı. Yenidən cəhd edin.','Site report sent successfully.' => 'Sayt hesabatı uğurla göndərildi.','Enable and send now' => 'Aktivləşdirin və indi göndərin','Close' => 'Bağla','A site report request is already in progress. Try again in a moment.' => 'Sayt hesabatı sorğusu artıq davam edir. Bir an sonra yenidən cəhd edin.','Site environment reporting is disabled.' => 'Sayt mühiti hesabatı deaktiv edilib.','No site report data is available to send.' => 'Göndərilə biləcək sayt hesabatı məlumatları yoxdur.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Bu sayt domeni ətraf mühit hesabatları göndərə bilmir (yerli və ya inkişaf domenləri istisna olunur).','A site report was sent recently. Try again later.' => 'Sayt hesabatı bu yaxınlarda göndərildi. Daha sonra yenidən cəhd edin.','The site report could not be sent. Try again later.' => 'Sayt hesabatı göndərilə bilmədi. Daha sonra yenidən cəhd edin.','Site environment reporting is not available.' => 'Sayt mühiti hesabatı mövcud deyil.','No site report data is available for the selected settings.' => 'Seçilmiş parametrlər üçün sayt hesabatı məlumatları mövcud deyil.','You are not allowed to manage site reports.' => 'Sayt hesabatlarını idarə etməyə icazəniz yoxdur.','PRO feature' => 'PRO xüsusiyyəti','Other plugins' => 'Digər plaginlər','Get only this add-on &mdash; %s' => 'Yalnız bu əlavəni əldə edin — %s','Install add-on' => 'Əlavəni quraşdırın','Upgrade to PRO &mdash; %s' => 'PRO versiyasına yüksəldin — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'Bu seçimlərin kilidini açmaq üçün <a target="_blank" href="%1$s">%2$s əldə edin</a> .','Add-on' => 'Əlavə','View documentation' => 'Sənədlərə baxın','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Sorğular daxil olmuş WordPress istifadəçisi tələb edir. Cari istifadəçinin məlumatlarından istifadə etmək üçün user_id-ni buraxın və ya zəng edən həmin istifadəçini redaktə edə bildikdə (edit_user qabiliyyəti) başqa bir hesabı hədəfləmək üçün user_id-ni ötürün. Təsdiqlənməmiş sorğular fc_api_forbidden qaytarır. Yanlış user_id fc_api_user_not_found qaytarır.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'İşləyici faydalı yükü qaytardıqda HTTP 200 { &quot;data&quot;: { ... } } ilə.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'Heç bir faydalı yük olmadıqda (məsələn, DELETE) { &quot;success&quot;: true } ilə HTTP 200.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Xətalar WP_Error-dan WordPress REST xətası JSON qaytarır (kod, mesaj, data.status). Tel kodları fc_api_* prefiksindən istifadə edir.','Forbidden access.' => 'Qadağan olunmuş giriş.','Target user was not found.' => 'Hədəf istifadəçi tapılmadı.','This feature is not available.' => 'Bu xüsusiyyət mövcud deyil.','A required address field is missing.' => 'Tələb olunan ünvan sahəsi yoxdur.','Postcode or ZIP is invalid.' => 'Poçt kodu və ya poçt indeksi yanlışdır.','Phone number is invalid.' => 'Telefon nömrəsi yanlışdır.','State or county is invalid.' => 'Ştat və ya qraflıq etibarsızdır.','Country is invalid or has no address fields.' => 'Ölkə yanlışdır və ya ünvan sahələri yoxdur.','The request could not be processed.' => 'Sorğu emal edilə bilmədi.','Back to previous step' => 'Əvvəlki addıma qayıt','Skip to settings' => 'Parametrlərə keçin','Start over and return to the first guided setup step' => 'Yenidən başlayın və ilk rəhbərli quraşdırma addımına qayıdın','Start over' => 'Yenidən başlayın','Please complete all sub-steps before continuing.' => 'Davam etməzdən əvvəl bütün alt addımları tamamlayın.','Expand' => 'Genişləndirin','Collapse' => 'Yığcamlaşdır','Skip' => 'Keçin','Mark as complete' => 'Tamamlanmış kimi qeyd edin','Mark as incomplete' => 'Yarımçıq kimi qeyd edin','View full-size image: %s' => 'Tam ölçülü şəkli göstər: %s','Full-size setup guide image' => 'Tam ölçülü quraşdırma təlimatı şəkli','Close image' => 'Şəkli bağlayın','Fluid Checkout Guided Setup' => 'Maye Ödənişi Rəhbərli Quraşdırma','Welcome' => 'Xoş gəlmisiniz','Explore your checkout' => 'Kassa xidmətinizi araşdırın','All set' => 'Bütün hazırdır','You do not have permission to access this page.' => 'Bu səhifəyə daxil olmaq üçün icazəniz yoxdur.','Go to step %1$d: %2$s' => '%1$d addımına keçin: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Bu təlimatlı quraşdırma sizə Maye Ödənişi ilə tanış olmağa kömək edir. Aşağıdakı addımlar hələlik əvəzedicilərdir.','Continue to the next step when you are ready.' => 'Hazır olduqda növbəti addıma keçin.','Open your store checkout to see Fluid Checkout in action.' => 'Maye Ödənişinin necə işlədiyini görmək üçün mağazanızın kassasını açın.','View checkout page' => 'Ödəniş səhifəsinə baxın','You can return to Fluid Checkout settings to continue configuring your store.' => 'Mağazanızı konfiqurasiya etməyə davam etmək üçün Maye Ödəniş parametrlərinə qayıda bilərsiniz.','Review checkout and cart settings' => 'Sifariş və səbət parametrlərini nəzərdən keçirin','Explore add-ons from the dashboard' => 'Əlavələri idarəetmə panelindən araşdırın','Finish & go to settings' => 'Bitir və parametrlərə keçin','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce konvensiyalarına uyğun olaraq faktura telefonu sahəsinin görünürlük seçimini köhnə dəyərdən yeniləyin.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Göndərmə telefonu sahəsinin görünürlük seçimini köhnə dəyərdən WooCommerce konvensiyalarına uyğunlaşdırmaq üçün yeniləyin.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Sifariş xülasəsi fon rəngi parametrini yeni Split dizayn ikinci sütun fon rəngi seçiminə kopyalayın.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Biteship plaginindən istifadə edərkən təkmilləşdirilmiş sahə seçimi funksiyası həmişə deaktiv olur.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'German Market istifadə edərkən sifariş mövqeyi həmişə &quot;Sifariş xülasəsinin altında&quot; olaraq təyin olunur. Bu plagin sifariş xülasəsinin altında sifariş düyməsinin və hüquqi onay qutularının göstərilməsini tələb edir.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce üçün Germanized istifadə edərkən sifariş mövqeyi həmişə &quot;Sifariş xülasəsinin altında&quot; olaraq təyin olunur. Bu plagin sifariş xülasəsinin altında sifariş düyməsinin və hüquqi onay qutularının göstərilməsini tələb edir.','Edit pickup locations' => 'Götürmə yerlərini redaktə edin','Use local pickup label from WooCommerce settings' => 'WooCommerce parametrlərindən yerli götürmə etiketindən istifadə edin','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Aktivləşdirildikdə, ödənişdəki götürmə seçim etiketi WooCommerce götürmə yeri parametrlərindəki başlıqla uyğun gəlir. Deaktiv edildikdə, etiket Fluid Checkout-dan tərcümə edilə bilən &quot;Yerli götürmə&quot; mətnindən istifadə edir.','Button label for applying coupon codesApply' => 'Müraciət edin','Checkout step titleContact' => 'Əlaqə','Checkout step titleShipping' => 'Çatdırılma','Checkout step titleBilling' => 'Faturalandırma','Checkout step titlePayment' => 'Ödəniş','Checkout substep change link labelChange' => 'Dəyişmək','Checkout substep save link labelSave changes' => 'Dəyişiklikləri yadda saxlayın','Substep review textNone.' => 'Heç biri.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Heç bir şəkil seçilmədi.','Settings sectionCart' => 'Səbət','Settings sectionOrder pay' => 'Sifariş ödənişi','Settings sectionThank you' => 'təşəkkür edirəm','Settings section titleIntegrations' => 'İnteqrasiyalar','Settings section titleLicense keys' => 'Lisenziya açarları','Captcha positionBefore place order section' => 'Sifariş vermədən əvvəl bölmə','Captcha positionBefore place order button' => 'Sifariş vermədən əvvəl düymə','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Bağlayın','Log in link label at checkout contact stepLog in' => 'Daxil ol','Log in separator label at for when guest checkout is disabledOr continue below' => 'Və ya aşağıda davam edin','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Və ya qonaq olaraq davam edin','Clear image selection on admin pages.Remove image' => 'Şəkli silin','shipping packagesShipping %d' => 'Göndərmə %d','shipping packagesShipping' => 'Göndərmə','Used as fallback for "Proceed to next step" button labelnext step' => 'növbəti addım','Substep review checkbox valueYes' => 'Bəli','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Con','Dummy customer last name in the admin previewDoe' => 'Doe','Dummy customer company in the admin previewExample Company' => 'Nümunə Şirkət','Dummy customer street address in the admin preview123 Main Street' => '123 Əsas Küçə','Dummy customer city in the admin previewAnytown' => 'İstənilən şəhər','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Zəhmət olmasa, bağlamanı ön qapıda qoyun.','Dummy product name in the admin previewBeanie' => 'Beanie','Dummy product name in the admin previewCap' => 'Qapaq','Dummy product name in the admin previewT-Shirt' => 'Futbolka','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Sifarişinizi aldıq və çatdırılma zamanı sizə yeniləmə göndərəcəyik.','Dummy download in the admin previewUser guide' => 'İstifadəçi təlimatı','Google Places API versionsPlaces API (New)' => 'Yerlər API-si (Yeni)','Google Places API versionsPlaces API (Legacy)' => 'Yerlər API-si (Köhnə)','Brasil API versionsVersion 1' => 'Versiya 1','Brasil API versionsVersion 2' => 'Versiya 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
